mapper.select:
SELECT 
FROM ActivityHotDeals a left join GoodsSku sku on a.skuId = sku.id
WHERE a.ID = #{id}

SELECT

FROM ActivityHotDeals a left join GoodsSku sku on a.skuId = sku.id
WHERE 1 = 1

    AND a.id = #{id}


    AND a.activityName LIKE CONCAT('%',#{activityName}, '%') 


    AND a.skuId = #{skuId}


    AND a.spuId = #{spuId}


    AND a.activityPrice = #{activityPrice}


    AND a.balancePayment = #{balancePayment}


    AND a.activitySumNum = #{activitySumNum}


    AND a.activityRobotNum = #{activityRobotNum}


    AND a.activitySumRound = #{activitySumRound}


    AND a.activitySumStock = #{activitySumStock}


    AND a.activityStartTime = #{activityStartTime}


    AND a.activityEndTime = #{activityEndTime}


    AND a.status = #{status}


    AND a.actCurrentRound = #{actCurrentRound}


    AND a.actCurrentPurchasedNum = #{actCurrentPurchasedNum}


    AND a.actCurrentAccountNum = #{actCurrentAccountNum}

order by  a.createTime desc
